using System.Globalization; using System.Security.Cryptography; using System.Text; using MiniStore.Application.Dtos.Accounting; using MiniStore.Application.Services; using MiniStore.Domain.Entities; using MiniStore.Domain.Interfaces; using MiniStore.Domain.Interfaces.Accounting;
namespace MiniStore.Application.Services.Accounting;
public sealed class BankStatementService(IBankStatementRepository statements,IAccountRepository accounts,IBankReconciliationRepository reconciliation)
{
 public async Task<BankStatementWorkspaceDto> GetAsync(){var a=await statements.GetAccountsAsync();var i=await statements.GetImportsAsync();return new(a.Select(x=>new BankAccountDto(x.Id,x.Name,x.MaskedIdentifier,x.CurrencyCode,x.AccountId)).ToList(),i.Select(x=>new BankStatementImportDto(x.Id,x.BankAccountId,x.FileName,x.ImportedAtUtc,x.LineCount,x.Lines.OrderBy(y=>y.LineNumber).Select(y=>new BankStatementLineDto(y.Id,y.TransactionDate,y.ValueDate,y.Description,y.Reference,y.Debit,y.Credit,y.RowVersion)).ToList())).ToList());}
 public async Task<BankStatementWorkspaceDto> CreateAccountAsync(CreateBankAccountDto dto){if(await accounts.GetByIdAsync(dto.AccountId) is null)throw new ArgumentException("Select a valid ledger account.");await statements.AddAccountAsync(new BankAccount(dto.Name,dto.MaskedIdentifier,dto.CurrencyCode,dto.AccountId));await statements.SaveChangesAsync();return await GetAsync();}
 public async Task<BankStatementWorkspaceDto> ImportAsync(int accountId,string fileName,byte[] content){var account=await statements.GetAccountAsync(accountId)??throw new ArgumentException("Select a valid bank account.");if(content.Length==0||content.Length>2_000_000)throw new ArgumentException("The CSV file must be between 1 byte and 2 MB.");var hash=Hash(content);if(await statements.ImportExistsAsync(account.Id,hash))throw new ArgumentException("This bank statement was already imported.");var rows=Parse(content);var lines=new List<BankStatementLine>();foreach(var r in rows){var fp=Hash(Encoding.UTF8.GetBytes($"{account.Id}|{r.Date:yyyyMMdd}|{r.Reference.Trim().ToUpperInvariant()}|{r.Debit.ToString(CultureInfo.InvariantCulture)}|{r.Credit.ToString(CultureInfo.InvariantCulture)}"));if(await statements.LineExistsAsync(account.Id,fp))throw new ArgumentException($"Duplicate bank transaction reference: {r.Reference}.");lines.Add(new BankStatementLine(r.Line,r.Date,r.ValueDate,r.Description,r.Reference,r.Debit,r.Credit,fp));}await statements.AddImportAsync(new BankStatementImport(account.Id,fileName,hash,lines));await statements.SaveChangesAsync();return await GetAsync();}
 public async Task<BankStatementCandidatesDto> GetCandidatesAsync(int lineId){var imports=await statements.GetImportsAsync();var import=imports.FirstOrDefault(x=>x.Lines.Any(l=>l.Id==lineId))??throw new ArgumentException("Statement line was not found.");var line=import.Lines.Single(x=>x.Id==lineId);var account=await statements.GetAccountAsync(import.BankAccountId)??throw new ArgumentException("Bank account was not found.");var rows=await reconciliation.GetCandidatesAsync(account.AccountId,line.TransactionDate.AddDays(-7),line.TransactionDate.AddDays(7),line.Debit>0);return new(lineId,rows.Select(x=>new BankStatementCandidateDto(x.JournalEntryId,x.JournalEntryLineId,x.EntryNumber,x.Date,x.Description,x.Debit,x.Credit)).ToList());}
 private static string Hash(byte[] x)=>Convert.ToHexString(SHA256.HashData(x));
 private static List<(int Line,DateTime Date,DateTime? ValueDate,string Description,string Reference,decimal Debit,decimal Credit)> Parse(byte[] bytes){var text=Encoding.UTF8.GetString(bytes).TrimStart('\uFEFF');var rows=text.Split(new[]{"\r\n","\n"},StringSplitOptions.RemoveEmptyEntries);if(rows.Length<2)throw new ArgumentException("CSV must contain a header and at least one row.");var h=rows[0].Split(',').Select((x,i)=>new KeyValuePair<string,int>(x.Trim(),i)).ToDictionary(x=>x.Key,x=>x.Value,StringComparer.OrdinalIgnoreCase);foreach(var n in new[]{"TransactionDate","Description","Reference","Debit","Credit"})if(!h.ContainsKey(n))throw new ArgumentException($"CSV column is required: {n}.");var result=new List<(int,DateTime,DateTime?,string,string,decimal,decimal)>();for(var line=1;line<rows.Length;line++){var c=rows[line].Split(',');string V(string n)=>h[n]<c.Length?c[h[n]].Trim():"";if(!DateTime.TryParse(V("TransactionDate"),CultureInfo.InvariantCulture,DateTimeStyles.None,out var date)||!decimal.TryParse(V("Debit"),NumberStyles.Number,CultureInfo.InvariantCulture,out var debit)||!decimal.TryParse(V("Credit"),NumberStyles.Number,CultureInfo.InvariantCulture,out var credit)||(debit<=0)==(credit<=0)||string.IsNullOrWhiteSpace(V("Description"))||string.IsNullOrWhiteSpace(V("Reference")))throw new ArgumentException($"Invalid CSV row {line+1}.");DateTime? value=null;if(h.ContainsKey("ValueDate")&&!string.IsNullOrWhiteSpace(V("ValueDate"))){if(!DateTime.TryParse(V("ValueDate"),CultureInfo.InvariantCulture,DateTimeStyles.None,out var v))throw new ArgumentException($"Invalid value date at row {line+1}.");value=v;}result.Add((line,date,value,V("Description"),V("Reference"),debit,credit));}return result;}
}
